import ee
import math

# Initialize Earth Engine
try:
    ee.Initialize()
except Exception:
    ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
seattle = ee.Geometry.Point([-122.3321, 47.6062]).buffer(15000)  # ~15 km buffer
periods = {
    2019: ('2019-09-01', '2019-12-01'),
    2020: ('2020-09-01', '2020-12-01'),
    2021: ('2021-09-01', '2021-12-01'),
}
scale_m = 5500  # ~CHIRPS native resolution

def get_chirps_stats(start, end, geom):
    col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY') \
        .filterDate(start, end) \
        .filterBounds(geom)
    size = col.size().getInfo()
    if size == 0:
        return {'ok': False, 'reason': 'empty', 'source': 'CHIRPS', 'size': 0}
    sum_img = col.select('precipitation').sum()
    # Pixel count and mean total mm over the period
    count = sum_img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=scale_m,
        maxPixels=1e9,
    ).get('precipitation').getInfo()
    if (count is None) or (int(count) == 0):
        return {'ok': False, 'reason': 'no_valid_pixels', 'source': 'CHIRPS', 'size': size}
    mean_mm = sum_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom,
        scale=scale_m,
        maxPixels=1e9,
    ).get('precipitation').getInfo()
    if (mean_mm is None) or (isinstance(mean_mm, float) and (math.isnan(mean_mm) or math.isinf(mean_mm))):
        return {'ok': False, 'reason': 'calc_fail', 'source': 'CHIRPS', 'size': size}
    return {'ok': True, 'size': size, 'count': int(count), 'total_mm': float(mean_mm), 'source': 'CHIRPS'}

def get_era5_stats(start, end, geom):
    # Fallback: ERA5-Land daily aggregated total precipitation (meters), convert to mm.
    try:
        col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR') \
            .filterDate(start, end) \
            .filterBounds(geom)
        size = col.size().getInfo()
        if size == 0:
            return {'ok': False, 'reason': 'empty', 'source': 'ERA5', 'size': 0}
        sum_img = col.select('total_precipitation_sum').sum()  # meters over period
        count = sum_img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=5000,
            maxPixels=1e9,
        ).get('total_precipitation_sum').getInfo()
        if (count is None) or (int(count) == 0):
            return {'ok': False, 'reason': 'no_valid_pixels', 'source': 'ERA5', 'size': size}
        mean_m = sum_img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=geom,
            scale=5000,
            maxPixels=1e9,
        ).get('total_precipitation_sum').getInfo()
        if (mean_m is None) or (isinstance(mean_m, float) and (math.isnan(mean_m) or math.isinf(mean_m))):
            return {'ok': False, 'reason': 'calc_fail', 'source': 'ERA5', 'size': size}
        mean_mm = float(mean_m) * 1000.0
        return {'ok': True, 'size': size, 'count': int(count), 'total_mm': mean_mm, 'source': 'ERA5'}
    except Exception:
        return {'ok': False, 'reason': 'error', 'source': 'ERA5', 'size': None}

def get_period_total_mm(year, start, end, geom):
    # Try CHIRPS first
    res = get_chirps_stats(start, end, geom)
    if not res['ok']:
        if res['reason'] == 'empty':
            # Try fallback ERA5-Land daily aggregated
            res2 = get_era5_stats(start, end, geom)
            if not res2['ok']:
                return res2  # propagate failure
            return res2
        else:
            return res
    return res

try:
    results = {}
    for yr, (start, end) in periods.items():
        stats = get_period_total_mm(yr, start, end, seattle)
        results[yr] = stats
        # Print concise evidence
        if stats.get('ok', False):
            print(f"{yr} Source: {stats['source']}, Images: {stats['size']}, Pixels: {stats['count']}, Total(mm): {stats['total_mm']:.1f}")
        else:
            reason = stats.get('reason', 'unknown')
            size = stats.get('size')
            print(f"{yr} Source: {stats.get('source')}, Issue: {reason}, Images: {size}")

    # Evaluate outcomes based on checks
    # Case C1: Empty collection for any year and fallback failed
    if any((not results[yr]['ok']) and (results[yr].get('reason') == 'empty') for yr in results):
        print("C1")
    # Case C2: No valid pixels after processing
    elif any((not results[yr]['ok']) and (results[yr].get('reason') == 'no_valid_pixels') for yr in results):
        print("C2")
    # Case C3: Calculation failure (None/NaN)
    elif any((not results[yr]['ok']) and (results[yr].get('reason') == 'calc_fail') for yr in results):
        print("C3")
    # Case D: Method/dataset error
    elif any((not results[yr]['ok']) and (results[yr].get('reason') in ['error']) for yr in results):
        print("D")
    else:
        v2019 = results[2019]['total_mm']
        v2020 = results[2020]['total_mm']
        v2021 = results[2021]['total_mm']
        # Final comparison: Is 2021 > 2020 and 2019?
        if (v2021 is None) or (v2020 is None) or (v2019 is None) or \
           any([math.isnan(v) or math.isinf(v) for v in [v2019, v2020, v2021]]):
            print("C3")
        elif (v2021 > v2020) and (v2021 > v2019):
            print("A")
        else:
            print("B")
except Exception as e:
    # Any unexpected error
    print("D")
